def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {3: 0, 1: 0}

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))

            by_row = {}
            for y, x in cells:
                by_row.setdefault(y, []).append(x)
            top, bottom = min(by_row), max(by_row)
            if len(by_row[top]) == 1:
                counts[3] += 1
            elif len(by_row[bottom]) == 1:
                counts[1] += 1

    out = [[0] * 6 for _ in range(3)]
    # Counts are shown in a two-row tally, filling left to right.
    positions = [(0, 0), (2, 0), (0, 2), (2, 2)]
    for color, col in ((3, 0), (1, 3)):
        for i in range(min(counts[color], 4)):
            r, offset = positions[i]
            out[r][col + offset] = color
    return out
